mapper.update:
UPDATE contract_endorsement
SET underwriting_request_id = #{underwritingRequestId}
WHERE endorsement_id = #{endorsementId}
  AND endorsement_status = 'APPLIED'

UPDATE contract_endorsement
SET endorsement_status = 'APPROVED',
    approved_at = #{approvedAt}
WHERE endorsement_id = #{endorsementId}
  AND endorsement_status = 'APPLIED'

UPDATE contract_endorsement
SET endorsement_status = 'REJECTED',
    rejected_at = #{rejectedAt}
WHERE endorsement_id = #{endorsementId}
  AND endorsement_status = 'APPLIED'

UPDATE contract_endorsement
SET endorsement_status = 'CANCELLED',
    cancelled_at = #{cancelledAt}
WHERE endorsement_id = #{endorsementId}
  AND endorsement_status = 'APPLIED'
